ALTER TABLE "charges" ADD CONSTRAINT "charges_source_or_reason" CHECK (num_nonnulls("charges"."bed_stay_id", "charges"."queue_entry_id") <= 1
      AND ((num_nonnulls("charges"."bed_stay_id", "charges"."queue_entry_id") = 0) = ("charges"."manual_reason" IS NOT NULL AND length(btrim("charges"."manual_reason")) > 0)));--> statement-breakpoint
ALTER TABLE "charges" ADD CONSTRAINT "charges_cancellation_complete" CHECK (("charges"."cancelled_at" IS NULL AND "charges"."cancelled_by" IS NULL AND "charges"."cancellation_reason" IS NULL)
      OR ("charges"."cancelled_at" IS NOT NULL AND "charges"."cancellation_reason" IS NOT NULL AND length(btrim("charges"."cancellation_reason")) > 0
          AND ("charges"."cancelled_by" IS NOT NULL OR "charges"."queue_entry_id" IS NOT NULL)));--> statement-breakpoint
ALTER TABLE "service_points" ADD CONSTRAINT "service_points_fee_at_a_clinic" CHECK ("service_points"."kind" = 'consultation' OR "service_points"."consultation_item_id" IS NULL);